/* Generated by safe ES module refactor from the existing js/main.js implementation. */

export function showMessage(message, type = "success") {
  let stack = document.getElementById("toast-stack");
  if (!stack) {
    stack = document.createElement("div");
    stack.id = "toast-stack";
    stack.className = "toast-stack";
    document.body.appendChild(stack);
  }

  const toast = document.createElement("div");
  toast.className = `toast ${type}`;
  toast.textContent = String(message || "");
  stack.appendChild(toast);

  window.setTimeout(() => {
    toast.classList.add("toast-hide");
    window.setTimeout(() => toast.remove(), 250);
  }, 3000);
}

export async function copyTextToClipboard(text, buttonEl, defaultText = "Copy Key") {
  if (!text || text === "--") return;

  const originalLabel = buttonEl ? buttonEl.textContent : defaultText;
  const originalClass = buttonEl ? buttonEl.className : "";

  function showCopiedState() {
    if (!buttonEl) return;
    buttonEl.textContent = "Copied";
    if (originalClass.includes("btn-neutral")) {
      buttonEl.className = originalClass.replace("btn-neutral", "btn-success");
    } else {
      buttonEl.classList.add("btn-success");
    }

    window.setTimeout(() => {
      buttonEl.textContent = originalLabel || defaultText;
      buttonEl.className = originalClass;
    }, 1800);
  }

  if (navigator.clipboard && window.isSecureContext) {
    try {
      await navigator.clipboard.writeText(text);
      showCopiedState();
      return;
    } catch (err) {
      /* Fall through to the legacy copy fallback. */
    }
  }

  try {
    const textArea = document.createElement("textarea");
    textArea.value = text;
    textArea.className = "hidden-textarea";
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();
    document.execCommand("copy");
    document.body.removeChild(textArea);
    showCopiedState();
  } catch (err) {
    showMessage("Copy failed. Please copy manually.", "error");
  }
}
